Local Ltac memset_call RT AF FKC PFS DIN dat rs lo v :=
  at_call RT AF ltac:(cbn [ivls_client]; split; [intros zz Hzz; left; ul| exact I])
                ltac:(fun Hx => cbn [outside]; destruct Hx as [Hx1 Hx2]; pose proof (PFS _ (conj Hx1 Hx2)); cbn [outside] in Hx2; split; [lia| exact I]);
  lazymatch goal with A : ART RT ?S ?mm |- cps _ (ASTA RT ?S _ (eq (entry_st _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?mm))) _ =>
    let WRD := fresh "WRD" in let ACCD := fresh "ACCD" in
    pose proof (af_acc_live RT AF S mm dat rs A DIN) as (WRD & ACCD);
    eapply cps_seq;
    [ let MS0 := fresh "MS0" in
      pose proof (fk_asan_memset RT FKC) as MS0; unfold memset_icontractF in MS0;
      eapply MS0 with (lo := lo) (d := dat) (n := rs) (c := Z_to_bv 8 255); rt_side idtac;
      lazymatch goal with
      | |- (0 <= _ <= _) => change (2^47) with 140737488355328; lia
      | |- (0 <= _ < _) => lia
      | |- checked_dst _ _ _ _ _ _ =>
          unfold checked_dst; rewrite ?unsigned_lit by lia; split; [intros _; split; [exact ACCD| left; exists dat, rs; split; [exact DIN| lia]]|];
          split; [intros i Hi; right; right; left; exists dat, rs; split; [exact DIN| lia]| exact WRD]
      | |- Z_to_bv 64 _ = Z_to_bv 64 _ =>
          first [ reflexivity
                | f_equal; unfold zx32; rewrite ?unsigned_lit by lia; rewrite ?Z.mod_small by lia; unfold rs; lia
                | f_equal; unfold zx32; rewrite !(unsigned_lit (p_wpl v)), !(unsigned_lit (p_h v)) by lia;
                  rewrite (Z.mod_small (p_wpl v)), (Z.mod_small (p_h v)) by lia;
                  rewrite !(unsigned_lit (p_wpl v)), !(unsigned_lit (p_h v)) by lia;
                  rewrite (Z.mod_small (p_wpl v * 4)) by lia; unfold rs; lia
                | match goal with |- ?g => idtac "LEFTOVER-EQ:" g end ]
      | |- ?g => idtac "LEFTOVER:" g
      end | ] end.

